import{basename}from"node:path";import{resolveInstalledPackageInfo}from"#internal/application/package.js";import{DEVELOPMENT_WORKER_APP_ROOT_ENV}from"#internal/workflow/development-world-protocol.js";import{installLocalInstrumentationRuntime}from"#tracing/local/instrumentation-runtime.js";function installLocalTracing(e){let t=process.env[DEVELOPMENT_WORKER_APP_ROOT_ENV];if(t===void 0)throw Error(`${DEVELOPMENT_WORKER_APP_ROOT_ENV} is required for local tracing.`);let n=installLocalInstrumentationRuntime({appRoot:t,frameworkVersion:resolveInstalledPackageInfo().version,serviceName:basename(t)});e.hooks.hook(`close`,()=>n.shutdown())}export{installLocalTracing};